<template>
  <div class="type" >
    <div class="img-box">
      <img :src="typeData.bg_img" alt="" v-if="typeData.bg_img" ref="typeImg" :style="'height:' + imgHeight + 'px'">
      <div class="bg" :style="bgStyle" v-else ref="typeImg">
        <div class="first-name">{{typeData.cat_name}}</div>
        <div class="second-name">{{typeData.sub_title}}</div>
      </div>
      <div class="fixed-more">
        <div class="see-more" @click="goToType">查看更多<i class="icon iconfont">&#xe629;</i></div>
        <i class="icon iconfont bottom-arrow">&#xe62b;</i>
      </div>
    </div>
    <div class="goods-list" v-if="typeData.goods_list.length > 0">
        <div class="swiper-container" ref="typeGoods">
            <div class="swiper-wrapper">
              <div class="swiper-slide" v-for="(item, index) in typeData.goods_list" :key="index" >
                <div class="item" @click="checkGoodsDetail(item.goods_id)">
                  <div class="goods-img">
                    <img class="img" :src="item.image" alt="">
                    <img class="icon" v-if="item.labels && item.labels.type == 1" :src="item.labels.image" alt="">
                    <span class="icon txt-icon main-color-bg" v-if="item.labels && item.labels.type == 0" :style="{background:'-webkit-linear-gradient(top,'+ item.labels.color +','+ item.labels.color2 +') !important'}">{{item.labels.name}}</span>
                  </div>
                  <div class="goods-title">{{ item.limit_buy == 0 ? '' : '【限购'+item.limit_buy+'份】' }}{{item.name}}</div>
                  <div class="price-box">
                    <div>
                      <div class="now main-color-font">¥{{item.price}}</div>
                      <div class="old">¥{{item.old_price}}</div>
                    </div>
                    <AddToCart v-if="item.stock_status == 0 && item.is_no_start == 0 && item.limit_buy_status == 0" type="small" :goodsId="item.goods_id"/>
                  </div>
                  <div class="close-buy" v-if="item.stock_status == 1 || item.is_no_start == 1 || item.limit_buy_status == 1">
                    <div class="icon-box">
                      <div class="icon" v-if=" item.stock_status == 1 ">已抢光</div>
                      <div class="icon" v-else-if=" item.is_no_start == 1 || item.limit_buy_status == 1">未开始</div>
                    </div>
                  </div>
                </div>
              </div>
              <div class="swiper-slide see-more" @click="goToType">
                <span>查看更多</span><i class="icon iconfont">&#xe622;</i>
              </div>
            </div>
          </div>
    </div>
  </div>
</template>

<script>
import Swiper from 'swiper'
import AddToCart from '../AddToCart/AddToCart'
export default {
  name: 'TypeGoods',
  data () {
    return {
      tyeGoodsScroll: '',
      bgStyle: '',
      imgHeight: ''
    }
  },
  props: [ 'typeData' ],
  created () {
    if (!this.typeData.bg_img) {
      this.bgStyle = `background:#${this.typeData.bg_color};`
    }
  },
  mounted () {
    this.$nextTick(() => {
      this.tyeGoodsScroll = new Swiper(this.$refs.typeGoods, {
        slidesPerView: 'auto'
      })

      this.imgHeight = this.$refs.typeImg.getBoundingClientRect().width * 206 / 640
      this.bgStyle += `height:${this.imgHeight}px`
      console.log('2222', this.imgHeight)
    })
  },
  methods: {
    checkGoodsDetail (id) {
      this.$router.push({ path: '/goods', query: { goodsId: id, leaderId: this.$util.storage.get('leader_id') } })
    },
    goToType () {
      this.$router.replace({ path: '/classify', query: { cat_id: this.typeData.cat_id } })
    }
  },
  components: {
    AddToCart
  }
}
</script>

<style lang="stylus" scoped>
  .type
    background #fff
    margin-top 10px
    .img-box
      padding 15px
      position relative
      img
        width 100%
        object-fit cover
        border-radius 5px
      .bg
        color #fff
        padding 15px
        border-radius 5px
        min-height 80px
        box-sizing border-box
        .first-name
          font-size 18px
          font-weight bold
          margin-bottom 8px
        .second-name
          font-size 14px
          height 14px
      .fixed-more
        position absolute
        left 0.8rem
        bottom 0.4rem
        .see-more
          margin-top 15px
          padding 2px 6px 0 10px
          border-radius 9px
          font-size 10px
          background rgba(0, 0, 0, .4)
          color #fff
          .icon
            vertical-align middle
        .bottom-arrow
          padding-left 25px
          color #fff
          font-size 18px
    .goods-list
      width 100%
      .swiper-container
        .swiper-slide
          width 95px
          margin-left 15px
          .item
            padding-bottom 15px
            .goods-img
              width 95px
              height 95px
              font-size 0
              position relative
              .img
                width 100%
                height 100%
                object-fit cover
              .icon
                position absolute
                top 0
                left 0
                width 30px
                background $color-main
                &.txt-icon
                  height 30px
                  color #fff
                  line-height 30px
                  font-size 12px
                  text-align center
                  overflow hidden
            .goods-title
              font-size 12px
              margin-top 5px
              line-height 1.5
              height 36px
              ellipsis(2)
            .price-box
              margin-top 10px
              flexbox()
              justify-content space-between
              align-items center
              line-height 1.3
              .now
                font-size 14px
                font-weight bold
                color $color-main
              .old
                color #999999
                text-decoration line-through
            .close-buy
              position absolute
              top 0
              left 0
              right 0
              bottom 0
              background rgba(255, 255, 255, .4)
              padding 20px
              .icon-box
                width 100%
                padding-top 100%
                position relative
                .icon
                  position absolute
                  top 0
                  left 0
                  right 0
                  bottom 0
                  background rgba(0, 0, 0, .5)
                  color #fff
                  border-radius 50%
                  flexbox()
                  justify-content center
                  align-items center
                  font-size 14px
          &.see-more
            padding 30px 25px
            width 16px
            line-height 1.3
            color #666666
            text-align center
            margin-left 0
            .icon
              color #999999
              margin-top 4px
              display inline-block
</style>
