import Vue from 'vue'
import api from '../../api/apiList'
var util = {
  app_appCallBack: null,
  checkWeixinApp: function () {
    if (window.__wxjs_environment === 'miniprogram' || (util.checkWeixin() && /(miniprogram)/.test(navigator.userAgent.toLowerCase()))) {
      return true
    } else {
      return false
    }
  },

  checkApp: function () {
    if (/(pigcmso2oreallifeapp)/.test(navigator.userAgent.toLowerCase())) {
      return true
    } else {
      return false
    }
  },

  checkIos: function () {
    if (/(iphone|ipad|ipod)/.test(navigator.userAgent.toLowerCase())) {
      return true
    } else {
      return false
    }
  },

  checkAndroid: function () {
    if (/(android)/.test(navigator.userAgent.toLowerCase())) {
      return true
    } else {
      return false
    }
  },

  checkWeixin: function () {
    if (/(micromessenger)/.test(navigator.userAgent.toLowerCase())) {
      return true
    } else {
      return false
    }
  },

  appFunction: function (obj) {
    // obj.name 调用app方法名
    if (!obj || !obj.name) {
      console.log('')
      return false
    }
    if (util.checkAndroid()) {
      window.pigcmspackapp[obj.name](JSON.stringify(obj))
    } else {
      window.webkit.messageHandlers.PackAppJSBridgeMethod.postMessage(obj)
    }
  },

  getTicket: function () {
    var reg = /ticket=(.*?),/
    var arr = reg.exec(navigator.userAgent)
    if (arr == null) {
      return ''
    } else {
      return arr[1]
    }
  },

  getDeviceid: function () {
    var reg = /device-id=(.*?),/
    var arr = reg.exec(navigator.userAgent)
    if (arr == null) {
      return ''
    } else {
      return arr[1]
    }
  },

  projectName: 'community_group',
  storage: {
    analysisKey (key) {
      if (key == 'ticket') {
        key = 'packapp_ticket'
      } else if (key == 'user') {
        key = 'packapp_user'
      } else if (key == 'device') {
        key = 'packapp_device'
      } else {
        key = util.projectName + '_' + key
      }
      return key
    },
    get: function (key) {
      key = util.storage.analysisKey(key)
      let temp = window.localStorage.getItem(key)
      if (temp) {
        return JSON.parse(temp)
      } else {
        return false
      }
    },
    set: function (key, value) {
      key = util.storage.analysisKey(key)
      window.localStorage.setItem(key, JSON.stringify(value))
    },
    remove: function (key) {
      key = util.storage.analysisKey(key)
      window.localStorage.removeItem(key)
    },
    clear: function () {
      window.localStorage.clear()
    }
  },

  // 检查登录
  checkLogin: function (loginFailUrl) {
    if (!loginFailUrl) {
      loginFailUrl = window.location.protocol + '//' + window.location.host + '/packapp/community_group/index.html'
    }
    let isLogin = util.storage.get('ticket')
    if (!isLogin) {
      location.replace(process.env.VUE_APP_BASE_API + '/packapp/my/login.html?back=' + encodeURIComponent(location.href) + '&visit=community_group' + '&loginFail=' + encodeURIComponent(loginFailUrl))
      return false
    } else {
      return true
    }
  },

  // 时间转换
  timestampToTime: function (s) {
    var day = Math.floor(s / 3600 / 24)
    var hours = Math.floor(s / 3600 % 24)
    var min = Math.floor(s / 60) % 60
    var sec = s % 60
    hours = util.add(hours)
    min = util.add(min)
    sec = util.add(sec)
    return { day, hours, min, sec }
  },

  // 添 0
  add: function (m) {
    return m < 10 ? '0' + m : m
  },

  getWxconfig: function (callback) {
    let _url = window.location.href.split('#')[0]
    console.log('请求wx.config开始')
    api.getWxConfig({ noTip: true, work: 'community_group', location_url: _url }).then((_lists) => {
      console.log('请求wx.config成功', _lists)
      // 注入配置
      Vue.prototype.$wx.config({
        debug: false,
        appId: _lists.appId,
        timestamp: _lists.timestamp,
        nonceStr: _lists.nonceStr,
        signature: _lists.signature,
        jsApiList: ['checkJsApi', 'onMenuShareTimeline', 'onMenuShareAppMessage', 'onMenuShareQQ', 'onMenuShareWeibo', 'scanQRCode', 'previewImage', 'openLocation', 'getLocation', 'getNetworkType']
      }, (e) => {
        console.log('请求wx.config报错', e)
      })

      Vue.prototype.$wx.ready(function () {
        Vue.prototype.$wx.checkJsApi({
          jsApiList: ['checkJsApi', 'onMenuShareTimeline', 'onMenuShareAppMessage', 'onMenuShareQQ', 'onMenuShareWeibo', 'scanQRCode', 'previewImage', 'openLocation', 'getLocation', 'getNetworkType'],
          success: function (res) {
            console.log('微信配置成功')
            callback && callback()
          }
        })
      })
    })
  },

  getLocation (successFunc) {
    if (util.checkWeixin()) {
      console.log('调用微信定位1')
      util.locationByWx(successFunc)
    } else if (util.checkApp()) {
      console.log('调用APP定位')
      util.locationByApp(successFunc)
    } else {
      console.log('调用H5定位')
      util.locationByH5(successFunc)
    }
  },

  locationByH5 (successFunc) {
    let options = {
      lng: '',
      lat: '',
      errorMsg: ''
    }
    if (!document.location.protocol == 'https:' || !navigator.geolocation) {
      options.errorMsg = '暂不支持定位'
      // Vue.prototype.$messageBox('提示', options.errorMsg)
      successFunc(options)
      return
    }
    navigator.geolocation.getCurrentPosition(
      function (position) {
        // 获取地理位置成功时所做的处理
        let lng = position.coords.longitude
        let lat = position.coords.latitude
        options.lng = lng
        options.lat = lat
        successFunc(options)
      },
      function (error) {
        // 获取地理位置信息失败时所做的处理
        switch (error.code) {
          case error.PERMISSION_DENIED:
            options['errorMsg'] = '获取位置信息失败,用户拒绝请求地理定位'
            break
          case error.POSITION_UNAVAILABLE:
            options['errorMsg'] = '获取位置信息失败,位置信息不可用'
            break
          case error.TIMEOUT:
            options['errorMsg'] = '获取位置信息失败,请求获取用户位置超时'
            break
          case error.UNKNOWN_ERROR:
            options['errorMsg'] = '获取位置信息失败,定位系统失效'
            break
        }
        // Vue.prototype.$messageBox('提示', options.errorMsg)
        successFunc(options)
      }, {
        // 以下是可选属性
        enableHighAccuracy: true, // 是否要求高精度的地理位置信息
        timeout: 4000 // 对地理位置信息的获取操作做超时限制，如果再该事件内未获取到地理位置信息，将返回错误
      })
  },
  getVersion () {
    var reg = /versioncode=(.*?),/
    var arr = reg.exec(navigator.userAgent.toLowerCase())
    if (arr == null) {
      return '85'
    } else {
      return arr[1]
    }
  },
  iosFunction (paramStr, paramObj) {
    var packVersion = util.getVersion()
    var str = parseFloat(packVersion) >= 1000
    if (str == true) {
      window.webkit.messageHandlers.appJSBridgeMethod.postMessage(paramObj)
    } else {
      var iframe = document.createElement('iframe')
      iframe.src = 'pigcmso2o://' + paramStr
      document.body.appendChild(iframe)
    }
  },
  locationByApp (successFunc) {
    util.app_appCallBack = successFunc
    if (util.checkAndroid()) {
      window.lifepasslogin.getLocation(true)
    } else {
      util.iosFunction('getLocation/true', { name: 'getLocation', timely: '1', callback: '' })
    }
  },
  locationByWx (successFunc) {
    let options = {
      lng: '',
      lat: '',
      errorMsg: ''
    }
    Vue.prototype.$wx.error(function (res) {
      if (typeof res == 'object' && res.errMsg) {
        Vue.prototype.$toast('微信接口报错' + res.errMsg)
      }
    })
    Vue.prototype.$wx.ready(function () {
      Vue.prototype.$wx.getLocation({
        type: 'wgs84',
        success: function (res) {
          var lng = res.longitude
          var lat = res.latitude
          options['lng'] = lng
          options['lat'] = lat
          console.log('微信定位成功', res, options)
          successFunc(options)
        },
        fail: function (res) {
          if (res.errMsg == 'getLocation:cancel' || res.errMsg == 'getLocation:fail') {
            options['errorMsg'] = '获取位置信息失败,用户拒绝请求地理定位'
          } else {
            options['errorMsg'] = res.errMsg
          }
          successFunc(options)
        },
        cancel: function (res) {
          if (res.errMsg == 'getLocation:cancel' || res.errMsg == 'getLocation:fail') {
            options['errorMsg'] = '获取位置信息失败,用户拒绝请求地理定位'
          } else {
            options['errorMsg'] = res.errMsg
          }
          successFunc(options)
        }
      })
    })
  },
  // GPS坐标转换成百度坐标
  getAdressDetail: function (lng, lat, callback) {
    var param = { ak: '4c1bb2055e24296bbaef36574877b4e2', callback: callback, coordtype: 'wgs84ll', location: lat + ',' + lng, output: 'json', pois: 1, jsoncallback: callback }
    if (util.checkApp()) {
      param.coordtype = 'bd09ll'
    }
    Vue.jsonp(`https://api.map.baidu.com/geocoder/v2/`, param).then(function (data) {
      console.log('请求百度解析地址成功', data)
      callback(data)
    }).catch(function (err) {
      console.log('请求百度解析地址失败', err)
      callback(err)
    })
  },
  wxShare: function (share) {
    let defaultUrl = window.location.protocol + '//' + window.location.host + '/packapp/community_group/redirect.html?app3Redirect=' + encodeURIComponent(window.location.href)
    Vue.prototype.$wx.ready(function () {
      Vue.prototype.$wx.onMenuShareAppMessage({
        title: share.title,
        desc: share.desc,
        link: share.sendFriendLink ? share.sendFriendLink : defaultUrl,
        imgUrl: share.share_img,
        success: function () {
          Vue.prototype.$toast('分享成功')
        }
      })
      Vue.prototype.$wx.onMenuShareTimeline({
        title: share.title,
        link: share.sendFriendLink ? share.sendFriendLink : defaultUrl,
        imgUrl: share.share_img,
        success: function () {
          Vue.prototype.$toast('分享成功')
        }
      })
      Vue.prototype.$wx.onMenuShareWeibo({
        title: share.title,
        desc: share.desc,
        link: share.sendFriendLink ? share.sendFriendLink : defaultUrl,
        imgUrl: share.share_img,
        success: function () {
          Vue.prototype.$toast('分享成功')
        }
      })
    })
  },
  setWxShare (shareData) {
    if (util.checkWeixinApp()) {
      Vue.prototype.$wx.miniProgram.postMessage({ data: shareData })
    }

    if (util.checkWeixin()) {
      if (util.checkAndroid()) {
        util.getWxconfig(util.wxShare(shareData))
      } else {
        util.wxShare(shareData)
      }
    }
  },

  cookie: {
    // 参数分别是cookie的名称，cookie的值，cookie的有效时间
    set: function (key, value, time) {
      let date = new Date()
      let expiresDays = time
      date.setTime(date.getTime() + expiresDays * 24 * 3600 * 1000)
      // 这里是添加到已有的cookie中， 不要弄成+=
      document.cookie = key + '=' + value + ';path=/;expores=' + date.toTimeString()
    },
    get: function (key) {
      let getCookie = document.cookie.replace(/[ ]/g, '')
      let arrCookie = getCookie.split(';')
      let tips
      for (let i = 0; i != arrCookie.length; i++) {
        let arr = arrCookie[i].split('=')
        if (key == arr[0]) {
          tips = arr[1]
          break
        }
      }
      return tips
    },
    delete: function (key) {
      let date = new Date()
      date.setTime(date.getTime() - 10000000)
      document.cookie = key + '= ;expores=' + date.toTimeString()
    }
  }
}

export default util
