const onChange = require('on-change')
// 全局变量
var globalData = {
  activityId: '',
  goodsId: '',
  goodsNumObj: {
    totalPrice: 0,
    totalNum: 0,
    selectNum: 0
  },
  selectedInfo: {},
  city: {
    area_id: 105,
    area_name: '合肥'
  }, // 选择的城市信息
  address: '', // 选择的地址信息
  code: '', // 提货码
  config: {}, // 基本配置信息
  couponId: '', // 优惠券ID
  nowAddress: '' // 用户当前地址
}
var res = JSON.parse(window.sessionStorage.getItem('community_group_globalData'))
if (res) {
  globalData = res
  for (var i in res) {
    if (i != 'goodsNumObj') {
      globalData[i] = res[i]
    }
  }
  console.log('从缓存中取出globalData', globalData)
}

// 监听全局变量的变化
const watchedGlobalData = onChange(globalData, function (key, value, oldVlue) {
  console.log('globalDta onchange', key, value, oldVlue)
  window.sessionStorage.setItem('community_group_globalData', JSON.stringify(globalData))
})

export default watchedGlobalData
